const ALLOW_EXT = new Set(['pdf','png','jpeg','jpg','gif','webp','heic','doc','docx','xls','xlsx','ppt','pptx','zip','txt','csv']);
const SKIP_MIME = /(?:calendar|ics|message\/rfc822|smime|vnd\.ms-outlook|winmail\.dat)/i;
const B4_PHRASES = /stáhnout fakturu|stáhnout doklad|stáhnout pdf|download invoice|download pdf|daňový doklad/i;
const PAYMENT_FROM = ['alza','neo','alzaneo','vodafone','o2','tmobile','t-mobile','innogy','cez','pre','eon','fakturoid'];
const MAX_FILE_BYTES = 25 * 1024 * 1024;

function asHeaderString(v) {
  if (v == null || v === '') return '';
  if (typeof v === 'string' || typeof v === 'number') return String(v);
  if (typeof v === 'object') {
    if (typeof v.value === 'string') return v.value;
    if (typeof v.text === 'string') return v.text;
    if (typeof v.email === 'string') {
      const n = v.name || v.displayName || '';
      return n ? `${n} <${v.email}>` : v.email;
    }
    if (Array.isArray(v)) return v.map(asHeaderString).filter(Boolean).join(', ');
    try { return JSON.stringify(v); } catch (_) { return ''; }
  }
  return String(v);
}

function headerOf(msg, name) {
  const want = String(name).toLowerCase();
  const headers = (msg && msg.payload && msg.payload.headers) || msg.headers || [];
  if (Array.isArray(headers)) {
    const row = headers.find((h) => String(h.name || '').toLowerCase() === want);
    return row ? asHeaderString(row.value) : '';
  }
  return asHeaderString(msg[name] || msg[String(name)] || '');
}


function decodePart(p) {
  if (!p || !p.body || !p.body.data) return '';
  try {
    const b64 = String(p.body.data).replace(/-/g, '+').replace(/_/g, '/');
    return Buffer.from(b64, 'base64').toString('utf8');
  } catch (_) { return ''; }
}
function extractBodies(msg) {
  const payload = msg.payload || msg;
  let html = '';
  let plain = '';
  function walk(p) {
    if (!p) return;
    const mime = String(p.mimeType || '').toLowerCase();
    if (mime === 'text/html' && p.body && p.body.data) html += decodePart(p);
    if (mime === 'text/plain' && p.body && p.body.data) plain += decodePart(p);
    if (Array.isArray(p.parts)) p.parts.forEach(walk);
  }
  walk(payload);
  if (!plain && !html) plain = asHeaderString(msg.text) || asHeaderString(msg.textPlain) || asHeaderString(msg.snippet) || asHeaderString(msg.html) || '';
  return { html, plain };
}
function htmlToText(html) {
  if (!html) return '';
  return String(html).replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<script[\s\S]*?<\/script>/gi,' ')
    .replace(/<br\s*\/?>/gi,'\n').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&')
    .replace(/\n{3,}/g,'\n\n').trim();
}
function isPaymentDoc(from, subject, body) {
  const f = String(from || '').toLowerCase();
  if (PAYMENT_FROM.some((t) => f.includes(t))) return true;
  if (/(faktur|vyúčtov|invoice|doklad|receipt|účtenk|platb|neo)/i.test(String(subject || ''))) return true;
  const b = String(body || '');
  if (/\b(\d{6,10})\b/.test(b) && /(\d[\d\s]*\s*(Kč|CZK|EUR|USD)|faktura|invoice|vyúčtov)/i.test(b)) return true;
  return false;
}
function extractB4Links(html, paymentDoc) {
  const links = [];
  const seen = new Set();
  if (!html) return links;
  const re = /<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const href = String(m[1] || '').trim();
    const anchor = String(m[2] || '').replace(/<[^>]+>/g, ' ').trim();
    if (!href || seen.has(href)) continue;
    const barePdf = /\.pdf(?:\?|#|$)/i.test(href);
    const phraseHit = B4_PHRASES.test(anchor) || B4_PHRASES.test(href);
    if (phraseHit || (barePdf && paymentDoc)) {
      seen.add(href);
      links.push(href);
    }
  }
  return links;
}
function extOf(name, mime) {
  const n = String(name || '').toLowerCase();
  const dot = n.lastIndexOf('.');
  if (dot >= 0) return n.slice(dot + 1);
  const m = String(mime || '').toLowerCase();
  if (m.includes('pdf')) return 'pdf';
  if (m.includes('png')) return 'png';
  if (m.includes('jpeg') || m.includes('jpg')) return 'jpg';
  if (m.includes('gif')) return 'gif';
  if (m.includes('webp')) return 'webp';
  if (m.includes('heic')) return 'heic';
  return '';
}
function shouldIncludeBinary(meta) {
  const fileName = String(meta.fileName || meta.filename || '').trim();
  const mime = String(meta.mimeType || meta.mime || '').toLowerCase();
  const size = Number(meta.fileSize || meta.size || 0);
  const disp = String(meta.contentDisposition || meta.disposition || '').toLowerCase();
  if (!fileName && mime === 'application/octet-stream') return false;
  if (!fileName && !size) return false;
  if (SKIP_MIME.test(mime) || /\.ics$/i.test(fileName)) return false;
  if (/winmail\.dat|smime/i.test(fileName + mime)) return false;
  const ext = extOf(fileName, mime);
  const isInlineImg = /^image\//i.test(mime) && /inline/i.test(disp);
  if (isInlineImg && size > 0 && size < 8192) return false;
  const hasAttachmentDisp = /attachment/i.test(disp);
  if (!hasAttachmentDisp && !fileName) return false;
  if (ext && !ALLOW_EXT.has(ext)) return false;
  if (size > MAX_FILE_BYTES) return false;
  return !!(fileName || hasAttachmentDisp);
}

const out = [];
for (const item of $input.all()) {
  const msg = item.json;
  const threadId = String(msg.threadId || $('Split messages').item.json.threadId || '').trim();
  const messageId = String(msg.id || msg.messageId || '').trim();
  const from = asHeaderString(headerOf(msg, 'from') || msg.From || msg.from);
  const to = asHeaderString(headerOf(msg, 'to') || msg.To || msg.to);
  const subject = asHeaderString(headerOf(msg, 'subject') || msg.Subject || msg.subject);
  const date = asHeaderString(headerOf(msg, 'date') || msg.Date || msg.date);
  const { html, plain } = extractBodies(msg);
  let bodyText = plain || htmlToText(html) || asHeaderString(msg.text) || asHeaderString(msg.snippet) || '';
  if (/<html|<div|<table/i.test(bodyText)) bodyText = htmlToText(bodyText) || bodyText;
  const paymentDoc = isPaymentDoc(from, subject, bodyText);
  const linkDownloads = extractB4Links(html, paymentDoc);

  const keptBin = {};
  let idx = 0;
  const skipped = [];
  for (const [key, b] of Object.entries(item.binary || {})) {
    const meta = {
      fileName: (b && (b.fileName || b.filename)) || key,
      mimeType: (b && b.mimeType) || '',
      fileSize: (b && (b.fileSize || b.size)) || 0,
      contentDisposition: (b && b.contentDisposition) || '',
    };
    if (shouldIncludeBinary(meta)) {
      keptBin['att_' + idx++] = b;
    } else {
      skipped.push({ name: meta.fileName, reason: 'b0-skip' });
    }
  }

  const row = {
    json: {
      threadId,
      messageId,
      messageMeta: { from, to, subject, date, bodyText },
      linkDownloads,
      b0Skipped: skipped,
    },
  };
  if (Object.keys(keptBin).length) row.binary = keptBin;
  out.push(row);
}
return out;

return (async () => {
const MAX_FILES = 20;
const byThread = new Map();

function addThread(threadId) {
  if (!byThread.has(threadId)) {
    byThread.set(threadId, { threadId, messages: [], binaries: [], b4Notes: [], b0Skipped: [] });
  }
  return byThread.get(threadId);
}

for (const item of $input.all()) {
  const j = item.json;
  const threadId = String(j.threadId || '').trim();
  if (!threadId) continue;
  const t = addThread(threadId);
  if (j.messageMeta) t.messages.push({ ...j.messageMeta, messageId: j.messageId });
  if (Array.isArray(j.b0Skipped)) t.b0Skipped.push(...j.b0Skipped);
  for (const [k, b] of Object.entries(item.binary || {})) {
    t.binaries.push({
      binary: b,
      name: (b && b.fileName) || k,
      size: Number((b && b.fileSize) || 0),
      source: 'mime',
    });
  }
  t.pendingLinks = t.pendingLinks || [];
  for (const url of j.linkDownloads || []) t.pendingLinks.push({ url, messageId: j.messageId });
}

async function downloadB4(url) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url,
    encoding: 'arraybuffer',
    returnFullResponse: true,
    timeout: 120000,
    skipSslCertificateValidation: false,
  });
}

for (const t of byThread.values()) {
  const seenUrls = new Set();
  for (const link of t.pendingLinks || []) {
    const url = String(link.url || '').trim();
    if (!url || seenUrls.has(url)) continue;
    seenUrls.add(url);
    try {
      const res = await downloadB4.call(this, url);
      const body = res.body || res;
      const buf = Buffer.isBuffer(body) ? body : Buffer.from(body);
      if (!buf.length) throw new Error('empty body');
      const b64 = buf.toString('base64');
      t.binaries.push({
        binary: {
          data: b64,
          mimeType: 'application/pdf',
          fileName: 'invoice-link.pdf',
          fileSize: buf.length,
        },
        name: 'invoice-link.pdf',
        size: buf.length,
        source: 'b4',
      });
    } catch (e) {
      t.b4Notes.push(`PDF z odkazu se nepodařilo stáhnout (${url}). Ulož prosím ručně do ~/Downloads.`);
    }
  }
  delete t.pendingLinks;
  if (t.binaries.length > MAX_FILES) {
    t.binaries = [...t.binaries].sort((a, b) => (b.size || 0) - (a.size || 0)).slice(0, MAX_FILES);
  }
  t.messages.sort((a, b) => String(a.date).localeCompare(String(b.date)));
}

return [...byThread.values()].map((t) => ({
  json: {
    threadId: t.threadId,
    messages: t.messages,
    binaries: t.binaries,
    b4Notes: t.b4Notes,
    b0Skipped: t.b0Skipped,
  },
}));
})();

const MAILBOX = 'workspace';
const staticData = $getWorkflowStaticData('global');
if (!staticData.attachmentsByThread) staticData.attachmentsByThread = {};
if (!staticData.fileByThread) staticData.fileByThread = {};

function yamlQuote(s) {
  return JSON.stringify(String(s || '').replace(/\n/g, ' '));
}
function safeName(raw) {
  return String(raw || 'attachment.bin').replace(/[/\\]/g, '-').trim() || 'attachment.bin';
}

const out = [];
const scratchUploads = [];
const scratchDeletes = [];

for (const item of $input.all()) {
  const j = item.json;
  const threadId = String(j.threadId || '').trim();
  if (!threadId) continue;
  const messages = j.messages || [];
  let subject = '';
  let firstFrom = '';
  let lastDate = '';
  const parts = [];
  for (const m of messages) {
    if (!subject && m.subject) subject = m.subject;
    if (!firstFrom && m.from) firstFrom = m.from;
    if (m.date) lastDate = m.date;
    parts.push(`### ${m.date || '?'}\n**From**: ${m.from || ''}\n**To**: ${m.to || ''}\n\n${m.bodyText || '_(prázdné tělo)_'}\n`);
  }
  subject = subject || 'no-subject';
  const filename = `sb-${MAILBOX}-${threadId}.md`;
  const stem = filename.replace(/\.md$/i, '');
  const fm = ['---','source: email',`mailbox: ${MAILBOX}`,`gmail_thread_id: ${yamlQuote(threadId)}`,`from: ${yamlQuote(firstFrom)}`,`subject: ${yamlQuote(subject)}`,`date: ${yamlQuote(lastDate)}`,'---',''].join('\n');
  let md = fm + `# Email: ${subject}\n\n**Mailbox**: ${MAILBOX}\n**Thread**: ${threadId}\n\n` + parts.join('\n---\n\n');
  if (j.b4Notes && j.b4Notes.length) {
    md += '\n\n> **Poznámka:** ' + [...new Set(j.b4Notes)].join(' ') + '\n';
  }

  const desiredNames = [];
  for (const b of j.binaries || []) {
    const uploadFileName = stem + '__' + safeName(b.name);
    desiredNames.push(uploadFileName);
    scratchUploads.push({
      json: { threadId, uploadFileName, skipUpload: false },
      binary: { data: b.binary },
    });
  }

  const oldAtt = staticData.attachmentsByThread[threadId] || [];
  for (const old of oldAtt) {
    if (old.fileId) {
      scratchDeletes.push({ json: { threadId, fileId: old.fileId, name: old.name || '' } });
    }
  }

  out.push({
    json: {
      filename,
      content: md,
      threadId,
      mailbox: MAILBOX,
      desiredNames,
      hasUploads: desiredNames.length > 0,
      hasDeletes: scratchDeletes.some((d) => d.json.threadId === threadId),
    },
  });
}

staticData._scratchUploads = scratchUploads;
staticData._scratchDeletes = scratchDeletes;
return out;

