  const mime = String(meta.mimeType || meta.mime || '').toLowerCase();
  const size = Number(meta.fileSize || meta.size || 0);
  const disp = String(meta.contentDisposition || meta.disposition || '').toLowerCase();
  if (!fileName && mime === 'application/octet-stream') return false;
  if (!fileName && !size) return false;
  if (SKIP_MIME.test(mime) || /\.ics$/i.test(fileName)) return false;
  if (/winmail\.dat|smime/i.test(fileName + mime)) return false;
  const ext = extOf(fileName, mime);
  const isInlineImg = /^image\//i.test(mime) && /inline/i.test(disp);
  if (isInlineImg && size > 0 && size < 8192) return false;
  const hasAttachmentDisp = /attachment/i.test(disp);
  if (!hasAttachmentDisp && !fileName) return false;
  if (ext && !ALLOW_EXT.has(ext)) return false;
  if (size > MAX_FILE_BYTES) return false;
  return !!(fileName || hasAttachmentDisp);
}

