    const link = a.webViewLink || a.webContentLink || a.url || '';
    const meta = [a.mimeType || a.mime || '', formatFileSize(a.size)].filter(Boolean).join(', ');
    lines.push(link ? `- [${name}](${link})${meta ? ` — ${meta}` : ''}` : `- ${name}${meta ? ` — ${meta}` : ''}`);
